const Q=window.QUESTIONS,E=window.RadioEngine,$=s=>document.querySelector(s),screen=$('#screen');
const topics={all:'All sectors',T1:'Rules & licenses',T2:'On-air operations',T3:'Radio waves',T4:'Your station',T5:'Electricity',T6:'Circuit lab',T7:'Troubleshooting',T8:'Signals & satellites',T9:'Antennas',T0:'Safety'};
const ranks=['Signal Scout','Wave Rider','Circuit Pilot','Orbit Operator','Galaxy Commander'];let state=E.fresh(),topic='all',view='home',audio,toastTimer,storageOK=true;
try{const raw=localStorage.getItem(E.KEY);if(raw)state=E.validate(JSON.parse(raw),Q);}catch(e){storageOK=false;$('#storage-warning').hidden=false;$('#storage-warning').textContent='Saved data could not be loaded. A fresh session is open. Use a backup to restore your progress.';}
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(state));storageOK=true;$('#storage-warning').hidden=true;}catch(e){storageOK=false;$('#storage-warning').hidden=false;$('#storage-warning').textContent='Your browser could not save progress. Download a backup in settings before leaving.';}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function rank(){return Math.min(4,Math.floor(state.xp/500));}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function unlock(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});}catch(e){}}
function sound(type){if(!state.sound)return;unlock();if(!audio)return;let notes=type==='right'?[523,659,784]:type==='wrong'?[330,247]:type==='rank'?[523,659,784,1047,1319]:type==='finish'?[392,523,659,784]:[740,988];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.105;o.type=type==='wrong'?'triangle':'sine';o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.08,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.24);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.25);});}
function soundUI(){const b=$('#sound');b.textContent=state.sound?'♫':'♪';b.setAttribute('aria-label',state.sound?'Mute sound':'Enable sound');b.setAttribute('aria-pressed',String(state.sound));b.style.color=state.sound?'var(--cyan)':'var(--muted)';}
function home(){view='home';const mastered=Object.values(state.stats).filter(v=>v.correct).length,total=Object.keys(state.stats).length,r=rank(),xp=state.xp%500;const a=state.session,active=a&&a.index<a.ids.length;screen.innerHTML=`<div class="topline"><span class="eyebrow">MISSION CONTROL</span><span class="save-note">${storageOK?'Progress saved on this device':'Progress not saved'}</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">CALLING ALL EXPLORERS</span><h1>Small radio.<br><span class="cyan">Big universe.</span></h1><p>Power up your signal.<br>One question at a time.</p><div class="sector-label">409 SIGNALS TO DISCOVER</div></div><div class="space-view" id="space-view" aria-hidden="true"><div class="fallback-orbit"></div></div></section><div class="rank-bar"><span class="rank-badge">✧</span><div class="rank-main"><div class="rank-labels"><strong>${ranks[r]}</strong><span>${r<4?500-xp+' XP to rank up':'MAX RANK'}</span></div><div class="bar"><i style="width:${r===4?100:xp/5}%"></i></div></div><div class="xp-total">${state.xp}<small>TOTAL XP</small></div></div>${active?`<button class="resume" id="resume"><span><strong>Resume your mission</strong><small>${a.mode==='retry'?'Retry missed':a.mode==='random'?'Random adventure':'Study in order'} · question ${a.index+1} of ${a.ids.length}</small></span><b>→</b></button>`:''}<div class="section-title"><h2>Choose your mission</h2><select id="topic" aria-label="Question topic">${Object.entries(topics).map(([k,v])=>`<option value="${k}" ${k===topic?'selected':''}>${v}</option>`).join('')}</select></div><div class="missions"><button class="mission" data-mode="order"><span class="mission-symbol">≋</span><strong>Campaign</strong><p>Study in order. Build your skills.</p><small>CONTINUE →</small></button><button class="mission" data-mode="random"><span class="mission-symbol">⤨</span><strong>Signal scramble</strong><p>Random questions. New adventures.</p><small>10 SIGNALS →</small></button><button class="mission" data-mode="retry" ${!state.missed.some(id=>topic==='all'||id.startsWith(topic))?'disabled':''}><span class="mission-symbol">↻</span><strong>Repair bay</strong><p>Replay missed signals. Get stronger.</p><small>${state.missed.filter(id=>topic==='all'||id.startsWith(topic)).length} TO RETRY →</small></button></div><div class="stats"><div class="stat"><strong>${state.missionsDone}</strong><span>Mission${state.missionsDone===1?'':'s'} completed</span></div><div class="stat"><strong>${mastered}<span> / 409</span></strong><span>Signals secured</span></div><div class="stat"><strong>${state.best} \u26A1</strong><span>Best answer streak</span></div><div class="stat"><strong>${Math.round(total/409*100)}%</strong><span>Pool explored</span></div></div>`;
$('#topic').onchange=e=>{topic=e.target.value;home();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>begin(b.dataset.mode));if(active)$('#resume').onclick=()=>{unlock();quiz();};window.dispatchEvent(new Event('space-mount'));window.scrollTo(0,0);}
function begin(mode){unlock();if(state.session&&state.session.index<state.session.ids.length){if(!confirm('Start a new mission? Your answers and missed questions stay saved, but this active mission will be replaced.'))return;}if(!E.start(state,Q,mode,topic)){toast('No missed questions in this sector. Try another mission!');return;}save();sound('start');quiz();}
function quiz(){const a=state.session;if(!a){home();return;}if(a.index>=a.ids.length){result();return;}view='quiz';const q=Q.find(q=>q.id===a.ids[a.index]),answered=a.selected!==null,ok=answered&&a.selected===q.answer,figure=q.question.match(/figure (T-\d)/i);screen.innerHTML=`<section class="quiz"><div class="quiz-nav"><button class="icon" id="back" aria-label="Save and return to mission control">‹</button><div class="bar"><i style="width:${(a.index+(answered?1:0))/a.ids.length*100}%"></i></div><small>${a.index+1} / ${a.ids.length}</small></div><div class="hud"><span class="eyebrow">${a.mode==='order'?'CAMPAIGN':a.mode==='random'?'SIGNAL SCRAMBLE':'REPAIR BAY'}</span><span class="pill">⚡ ${state.streak} streak · ${a.earned} XP</span></div><div class="signal-strip ${ok?'active':''}" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="height:${5+Math.abs(Math.sin(i*1.7))*18}px;animation-delay:${i*.017}s"></i>`).join('')}</div><div class="question-card"><div class="question-meta"><span>${q.id}</span><span>${topics[q.id.slice(0,2)]}</span></div><h2 id="question">${esc(q.question)}</h2>${figure?`<a class="figure" href="figure-${figure[1].toUpperCase()}.png" target="_blank" rel="noopener"><img src="figure-${figure[1].toUpperCase()}.png" alt="Official circuit diagram ${figure[1].toUpperCase()} with numbered components"><small>Tap diagram to open full size · pinch to zoom</small></a>`:''}</div><div class="answers" role="group" aria-labelledby="question">${q.options.map((o,i)=>`<button class="answer ${answered?(i===q.answer?'correct':i===a.selected?'wrong':'dim'):''}" data-answer="${i}" ${answered?'disabled':''}><span class="letter">${answered&&i===q.answer?'✓':answered&&i===a.selected?'×':'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div>${answered?`<div class="feedback ${ok?'':'retry'}" role="status"><strong>${ok?(state.streak>0&&state.streak%5===0?'Streak boost! +15 bonus XP':'Signal locked!'):'Signal lost. You can repair it.'}</strong><p>${ok?'Nice work. Your signal is getting stronger.':'Correct answer: '+ 'ABCD'[q.answer]+'. '+esc(q.options[q.answer])}</p><p class="source-note">${ok?'Correct answers earn 10 XP.':'Saved to Repair bay for another try.'} Answer key: ${q.id} (${ 'ABCD'[q.answer]})${q.ref?' · '+esc(q.ref):''}</p><button class="primary" id="next">${a.index===a.ids.length-1?'Mission results':'Next signal'} →</button></div>`:'<p class="idle-hint">No timer. Think it through, then tap an answer.</p>'}</section>`;
$('#back').onclick=()=>{save();home();};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const oldRank=rank(),r=E.answer(state,Q,Number(b.dataset.answer));if(!r)return;save();sound(rank()>oldRank?'rank':r.ok?'right':'wrong');if(rank()>oldRank)toast('Rank unlocked: '+ranks[rank()]+'!');quiz();window.dispatchEvent(new CustomEvent('signal-hit',{detail:{ok:r.ok}}));requestAnimationFrame(()=>$('.feedback')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));});if(answered)$('#next').onclick=()=>{E.next(state);save();if(a.index>=a.ids.length)sound('finish');quiz();window.scrollTo(0,0);};}
function result(){view='result';const a=state.session,perfect=a.correct===a.ids.length;screen.innerHTML=`<section class="result"><div class="result-icon">${perfect?'✦':'⌁'}</div><span class="eyebrow">MISSION COMPLETE</span><h1>${perfect?'Crystal-clear signal!':'One mission stronger.'}</h1><p>${perfect?'Every signal secured. Your next adventure is waiting.':'Every attempt builds your skills. Missed signals are ready in Repair bay.'}</p><div class="result-score">${a.correct}<small> / ${a.ids.length}</small></div><p>signals secured this mission</p><div class="results-mini"><div><strong>+${a.earned}</strong><span>XP earned</span></div><div><strong>${state.missionsDone}</strong><span>mission${state.missionsDone===1?'':'s'} completed</span></div><div><strong>${state.missed.length}</strong><span>signals to repair</span></div></div><div class="result-actions">${state.missed.length?'<button class="primary" id="retry-result">Repair missed signals →</button>':''}<button class="${state.missed.length?'secondary':'primary'}" id="again">${a.mode==='order'?'Next campaign mission':'Play another mission'} →</button><button class="secondary" id="return-home">Mission control</button></div></section>`;if($('#retry-result'))$('#retry-result').onclick=()=>{topic='all';begin('retry');};$('#again').onclick=()=>{topic=a.topic;begin(a.mode==='retry'?'random':a.mode);};$('#return-home').onclick=home;window.scrollTo(0,0);}
$('#home').onclick=()=>{unlock();save();home();};$('#sound').onclick=()=>{state.sound=!state.sound;save();soundUI();if(state.sound)sound('start');};$('#settings').onclick=()=>{unlock();$('#settings-dialog').showModal();};$('#close-settings').onclick=()=>$('#settings-dialog').close();$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='radio-quest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('File too large');const data=E.validate(JSON.parse(await file.text()),Q);if(!confirm('Replace this browser’s progress with this backup?'))return;state=data;save();soundUI();$('#settings-dialog').close();home();toast('Flight data restored. Ready for takeoff.');}catch(err){toast('That backup could not be read. Choose a Radio Quest JSON backup.');}finally{e.target.value='';}};addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();audio?.suspend();}else if(audio&&state.sound)audio.resume().catch(()=>{});});soundUI();home();
